"""rookery_views — the generated files of `rookery up`: workspace files and ROOKERY.md (D7, D15)."""
import datetime
import json
import os

import cli_init
import turn_block


def _stamp(command):
    t = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    return f"<!-- generated by rookery {command} at {t}; do not edit -->\n\n"


def _bullets(items):
    return "".join(f"- {x}\n" for x in items)


def _default_scope(role):
    if role == "writer":
        return (["change files in the worktree of this agent", "write notes under the runs folder of this agent"],
                ["change files outside the worktree of this agent", "change the files of another agent"])
    return (["read files and report the findings"],
            ["edit files", "run the server", "change the files of another agent"])


def _scope(agent):
    sc = agent.get("scope") or {}
    d_does, d_not = _default_scope(agent.get("role"))
    return (sc.get("does") or d_does), (sc.get("does_not") or d_not)


def _persona(agent):
    return agent.get("persona") or (
        f"You are {agent['name']}. You work as a {agent.get('role', 'reader')} in a team of agents. "
        "Do the task you get. Report what you did.")


def _persona_md(agent):
    return (f"# Persona of {agent['name']}\n\n{_persona(agent)}\n\n## Rules\n\n"
            + _bullets([
                "Read the roster in ROOKERY.md and _directory/INDEX.md before you ask the user.",
                "Ask another agent when it can answer. Ask the user only when no agent can.",
                "Stay inside your scope card.",
                "Send mail with the Rookery commands and the rookery block. Use no other way.",
                "Do not poll for mail. Rookery tells you when mail arrives.",
            ]))


def _card(a):
    does, not_does = _scope(a)
    return (f"### {a['name']}\n\n- Role: {a.get('role', 'reader')}\n"
            f"- Does: {'; '.join(does)}\n- Does NOT do: {'; '.join(not_does)}\n")


def _scope_md(agent, team):
    does, not_does = _scope(agent)
    out = (f"# Scope card of {agent['name']}\n\n## Does\n\n{_bullets(does)}\n"
           f"## Does NOT do\n\n{_bullets(not_does)}\n## Other agents in this team\n\n")
    others = [a for a in team.get("agents", []) if a["name"] != agent["name"]]
    if not others:
        return out + "None. You work alone.\n"
    return out + "\n".join(_card(a) for a in others)


def _body_md(agent, session):
    return f"""# {agent['name']}

You are **{agent['name']}**. Your agent ID is `{agent['agent_id']}`.
You work in the session `{session['name']}`. Your role is {agent.get('role', 'reader')}. Your harness is {agent.get('harness', 'claude')}.

## Mail

Rookery gives you durable mail. Use these commands only.

- Run `rookery inbox` to read your unread mail. It marks nothing as read.
- Run `rookery peek` to look at your mail and change nothing.
- Run `rookery ack ID ...` to mark mail as read. The last line of the inbox output shows the command.
- Run `rookery send TO "SAY"` to send one mail now.

To send mail at the end of a turn, end your final message with one fenced block. The info string is `rookery`.
The block holds one JSON object. Put nothing after it. Write no block when you have nothing to send.
You must set `to`, `task`, `kind`, `say` and `status`. Run `rookery identity show` if you need your name.
The full contract is in the Rookery skill.

```rookery
{{"to": "NAME", "task": "TASK-ID", "kind": "status", "say": "TEXT", "status": "in-progress"}}
```

Do not poll. Do not sleep. Do not schedule inbox checks.

## Where to look

- `ROOKERY.md` at the Rookery root says what each root folder holds.
- `CONTEXT.md` in this folder says how you stage your work.
- `_config/` in this folder holds your persona and your scope card.
"""


def _context_md(agent):
    return f"""# How {agent['name']} stages work

Keep each task in its own folder: `runs/<TASK-ID>/`. It has three stage folders.

- `01_intake`: the task, the mail and the files you got.
- `02_work`: your notes and drafts.
- `03_report`: the result that you hand over.

## HANDOFF.md

At the end of each turn, overwrite `runs/<TASK-ID>/HANDOFF.md`. Give it these four sections.

- `Last thing I did`
- `State now`
- `What is left`
- `Open threads`

A new session of you reads this file first. Write it so that a reader with no memory can continue.

Rookery never writes inside `runs/`, `outbox/` or `state/`. Do not edit the other files in this folder.
Rookery writes them again at the next start.
"""


def workspace_files(root, session, agent, team, host, command="up"):
    """Write the generated files of one agent workspace. Return the workspace path.
    Never writes inside runs/, outbox/ or state/, and never touches HANDOFF.md."""
    ws = turn_block.workspace(root, session["name"], agent["name"])
    stamp = _stamp(command)
    body = _body_md(agent, session)
    persona = _persona_md(agent)
    scope = _scope_md(agent, team)
    files = {
        "CLAUDE.md": body,
        "AGENTS.md": body,
        "CONTEXT.md": _context_md(agent),
        "_config/persona.md": persona,
        "_config/scope-card.md": scope,
        "_config/system-prompt.md": persona + "\n" + scope,
    }
    for rel, text in files.items():
        cli_init.write_text_atomic(os.path.join(ws, rel), stamp + text)
    for d in ("runs", "outbox", "state"):
        os.makedirs(os.path.join(ws, d), exist_ok=True)
    return ws


def rookery_md(root, command="up"):
    """Write ROOKERY.md at the root (L0 routing). Never writes CLAUDE.md or AGENTS.md."""
    text = """# Rookery root

This folder is the shared root of one project. Each folder has one job.

- `agents/`: one workspace for each agent, as `agents/<session>/<name>/`.
- `wt/`: the git worktrees of the writers.
- `_directory/`: who is here. Read `_directory/INDEX.md` for the roster.
- `_teams/`: one file for each session, with its task and members.
- `_threads/`: one line for each mail thread. It holds no mail body.
- `_mail/`: the metadata of held and quarantined mail. It holds no mail body.
- `logs/`: the logs of Rookery.
- `postmaster/`: the state of the postmaster.

Read your own `CLAUDE.md` in your workspace first. Read the roster before you ask the user.
Use the `rookery` commands to read and send mail.
"""
    path = os.path.join(root, "ROOKERY.md")
    cli_init.write_text_atomic(path, _stamp(command) + text)
    return path


def _committed_commands(repo):
    """The first Rookery handler per hook event in the repo's committed .claude/settings.json, as
    (matcher group, whole handler object). A missing or invalid file gives {}."""
    try:
        with open(os.path.join(repo, ".claude", "settings.json"), encoding="utf-8") as fh:
            hooks = json.load(fh).get("hooks")
    except (OSError, ValueError, AttributeError):
        return {}
    found = {}
    if not isinstance(hooks, dict):
        return found
    for event, _sub in cli_init.HOOK_EVENTS:
        groups = hooks.get(event)
        for g in groups if isinstance(groups, list) else []:
            for h in (g.get("hooks") if isinstance(g, dict) and isinstance(g.get("hooks"), list) else []):
                if event not in found and cli_init._is_rookery(h):
                    found[event] = (g, h)
    return found


def settings_json(path, project, repo=None):
    """Write the hooks file `_config/settings.json` (D8). With a repo that has the hooks committed,
    each event copies the whole committed handler (and its group matcher), so Claude Code runs the same handler once.
    Never writes the repo file or ~/.claude/settings.json."""
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    cli_init.merge_hooks(path, project, with_permissions=True)
    committed = _committed_commands(repo) if repo else {}
    if committed:
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
        for event, (cgroup, chandler) in committed.items():
            for g in data["hooks"][event]:
                for i, h in enumerate(g["hooks"]):
                    if cli_init._is_rookery(h):
                        g["hooks"][i] = json.loads(json.dumps(chandler))
                        if "matcher" in cgroup:
                            g["matcher"] = cgroup["matcher"]
        cli_init.write_text_atomic(path, json.dumps(data, indent=2, ensure_ascii=False) + "\n")
    return path
